'use strict';
const talentLabels={model:'Model',makeup:'Makeup artist',hair:'Hair artist',designer:'Fashion designer',agency:'Agency',hotel:'Hotel Management',photographer:'Photographer'};
const main=document.querySelector('#talent-main'),message=document.querySelector('#talent-message'),params=new URLSearchParams(location.search);
let account=null,activeConcept=null,boardMode='local';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(text){message.textContent=text;}
async function api(path,method='GET',body){const response=await fetch('/api/talent/'+path,{method,headers:body?{'content-type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Error(data.error||'Please try again.');return data;}
const avatar=(a,small=false)=>a.avatar?`<img class="talent-avatar ${small?'small':''}" src="${esc(a.avatar)}" alt="${esc(a.name)}">`:`<span class="talent-avatar ${small?'small':''}" aria-label="Profile photo not added">${esc((a.name||'?').split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</span>`;
const tags=roles=>roles.map(r=>`<span class="talent-tag">${esc(talentLabels[r]||r)}</span>`).join('');
const stateTag=s=>`<span class="talent-tag ${esc(s)}">${esc({requested:'Request sent',selected:'Selected',pending:'Awaiting agency approval',approved:'Enrolled',finalised:'Team finalised'}[s]||s)}</span>`;
function safeLink(v,label){try{const u=new URL(v);if(u.protocol==='https:')return `<a class="talent-inline" target="_blank" rel="noopener" href="${esc(u.href)}">${esc(label)}</a>`;}catch{}return '';}
function formError(form,error){form.querySelector('[role=status]').textContent=error.message;}
function wireForm(selector,work){const form=document.querySelector(selector);if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;form.querySelector('[role=status]').textContent='Saving…';try{await work(form,new FormData(form));}catch(error){formError(form,error);}finally{if(button.isConnected)button.disabled=false;}});}
function profileSettings(){return `<details><summary>My name, location & profile photo</summary><p class="talent-muted">Your profession is permanently ${esc(account.label)}. Your name, city and profile photo appear with your collaboration requests. Contact details in your portfolio remain your choice.</p><form id="account-form"><div class="talent-fields"><label>Your name<input name="name" maxlength="80" value="${esc(account.name)}" required></label><label>Home city<input name="city" maxlength="100" value="${esc(account.city)}" required></label></div><button class="talent-outline" type="submit">Save details</button><p class="talent-status" role="status"></p></form><label>Profile photo · JPEG, PNG or WebP, up to 5 MB<input id="account-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><p id="photo-status" role="status"></p><p><a class="talent-inline" href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out of GLOSS</a></p></details>`;}
function wireSettings(){wireForm('#account-form',async(form,data)=>{account=(await api('account','PATCH',Object.fromEntries(data))).account;form.querySelector('[role=status]').textContent='Saved.';});document.querySelector('#account-photo')?.addEventListener('change',async e=>{const file=e.target.files[0],status=document.querySelector('#photo-status');if(!file)return;if(file.size>5*1024*1024){status.textContent='Choose a photo under 5 MB.';return;}status.textContent='Uploading…';try{const response=await fetch('/api/talent/photo',{method:'PUT',headers:{'content-type':file.type},body:file}),data=await response.json();if(!response.ok)throw Error(data.error);account=data.account;status.textContent='Profile photo saved. It will appear in your shoot team.';}catch(error){status.textContent=error.message;}});}
function join(){const profession=document.body.dataset.profession,valid=Object.hasOwn(talentLabels,profession);if(account){main.innerHTML=`<p class="eyebrow">YOUR GLOSS ACCOUNT</p><h1>You’re a<br><em>${esc(account.label)}.</em></h1><p>${valid&&profession!==account.profession?'Your account is already registered to this profession. You can collaborate with other creatives from your own studio.':'Welcome back. Your studio is ready.'}</p><a class="button" href="/workspace">Open my studio</a>`;return;}main.innerHTML=`<a class="talent-back" href="/#made-for">Back to professions</a><p class="eyebrow">YOUR FIRST STEP</p><h1>Your craft.<br><em>Your GLOSS.</em></h1><p>Finish your GLOSS sign-up. One sign-in, one permanent profession. Your workspace and permissions follow that choice.</p><form class="talent-panel talent-form" id="join-form"><label>Your profession<select name="profession" required>${Object.entries(talentLabels).map(([id,label])=>`<option value="${id}" ${id===profession?'selected':''}>${esc(label)}</option>`).join('')}</select></label><div class="talent-fields"><label>Your professional name<input name="name" required maxlength="80" autocomplete="name"></label><label>Your city<input name="city" required maxlength="100" autocomplete="address-level2" placeholder="e.g. Mumbai"></label></div><label class="check"><input type="checkbox" name="confirm" required>I understand my profession cannot be changed later. I’ll only have my own profession’s workspace.</label><button class="button" type="submit">Create my GLOSS account</button><p class="talent-status" role="status"></p></form>`;wireForm('#join-form',async(form,data)=>{await api('account','POST',{...Object.fromEntries(data),confirm:data.has('confirm')});const next=params.get('next');location.href=next&&/^\/(collaborations|affiliations)(\?|$)/.test(next)?next:'/workspace';});}
function workspace(){const role=account.profession,creative=['model','makeup','hair','designer','photographer'].includes(role);const sample={model:'/samples/model',makeup:'/samples/makeup',hair:'/samples/hair',hotel:'/samples/chef'}[role];main.innerHTML=`<div class="talent-intro"><div><p class="eyebrow">${esc(account.label.toUpperCase())} / YOUR STUDIO</p><h1>Your work.<br><em>Your next chapter.</em></h1></div><div class="talent-identity">${avatar(account)}<div><b>${esc(account.name)}</b><br>${esc(account.city)}<br><span class="talent-tag">${esc(account.label)} account</span></div></div></div><p class="talent-muted">${role==='model'?'Already working? Bring your portfolio to life. Starting out? Build a team around your first concept, then approach the agencies that fit you.':role==='hotel'?'Choose your hotel role and build a resume around your experience, training and service standards.':role==='agency'?'Manage your enrolled agency, review model applications and keep track of your referrals.':'Bring your signature work together. Find a creative team and plan your next portfolio shoot.'}</p><div class="talent-grid">${role==='agency'?`<a class="talent-choice" href="/agency-dashboard"><span class="talent-symbol">G.</span><h3>My agency dashboard</h3><p>Enrol with GLOSS or open your approved agency’s referral dashboard.</p><strong>Open agency dashboard</strong></a><a class="talent-choice" href="/affiliations"><span class="talent-symbol">✳</span><h3>Model applications</h3><p>Review portfolio introductions and approve affiliations for your agency.</p><strong>Review applications</strong></a>`:`<a class="talent-choice" href="/portfolio"><span class="talent-symbol">G.</span><h3>${role==='model'?'Create your professional portfolio':role==='hotel'?'Create your tailored resume':'Create your living portfolio'}</h3><p>${role==='hotel'?'Reception, chef or hotel staff. Details tailored to the work you do.':'Add your portrait, classic resume, collections and video. Publish your own shareable link.'}</p><strong>${role==='hotel'?'Choose my hotel role':'Open portfolio builder'}</strong></a>${creative?`<a class="talent-choice" href="/collaborations"><span class="talent-symbol">+</span><h3>Collaborate.<br>Build your portfolio.</h3><p>Find concept shoots in your city, send a request or post a concept and choose your team.</p><strong>Find collaborations</strong></a>`:''}${role==='model'?`<a class="talent-choice" href="/affiliations"><span class="talent-symbol">✳</span><h3>Find your agency</h3><p>Apply to enrolled agencies. See pending applications and your confirmed affiliations.</p><strong>My agency affiliations</strong></a>`:''}`}</div>${sample?`<p><a class="talent-inline" href="${sample}" target="_blank">View ${esc(account.label.toLowerCase())} sample</a></p>`:''}${creative?'<section id="current-shoots" aria-label="Current shoots"><h2>On your call sheet.</h2><p>Loading your shoots and requests…</p></section>':''}${profileSettings()}`;wireSettings();if(creative)api('concepts').then(data=>{const rows=data.concepts.filter(c=>(c.mine||c.involved)&&['open','finalised'].includes(c.status));document.querySelector('#current-shoots').innerHTML='<h2>On your call sheet.</h2>'+(rows.length?'<div class="talent-grid">'+rows.map(c=>`<a class="talent-panel" href="/collaborations?concept=${esc(c.id)}"><p class="eyebrow">${esc(c.city)} / ${esc(c.date)}</p><h3>${esc(c.title)}</h3>${stateTag(c.status)}<p>${c.mine?'Your concept · manage requests':'Your request & shoot workspace'}</p></a>`).join('')+'</div>':'<p class="talent-muted">Your posted concepts, requests and selected teams will appear here.</p>');}).catch(()=>{document.querySelector('#current-shoots p').textContent='Open Collaborations to view your shoots and requests.';});}
async function board(){if(!['model','makeup','hair','designer','photographer'].includes(account.profession)){main.innerHTML='<h1>Your studio.</h1><p>Concept shoots are available to creative talent. Open your own workspace to continue.</p><a class="button" href="/workspace">My studio</a>';return;}main.innerHTML=`<a class="talent-back" href="/workspace">My studio</a><div class="talent-intro"><div><p class="eyebrow">COLLABORATE / CREATE / GET PORTFOLIO-READY</p><h1>Find your people.<br><em>Make the work.</em></h1></div><button id="new-concept" class="button" type="button">+ Post a concept</button></div><p>Find open concept shoots by city. You’ll apply as a ${esc(account.label.toLowerCase())}. The organiser selects the team; everyone agrees the terms before shooting.</p><form id="city-filter" class="talent-fields"><label>Location / city<input name="city" value="${esc(account.city)}" required maxlength="100"></label><div class="talent-actions"><button class="talent-outline" type="submit">Find collaborations</button></div></form><div class="talent-tabs"><button class="talent-outline" data-board="local" aria-pressed="true">Open in this city</button><button class="talent-outline" data-board="mine" aria-pressed="false">My shoots & requests</button></div><p id="board-status" role="status">Loading concepts…</p><div id="concept-list" class="talent-grid"></div>`;document.querySelector('#new-concept').onclick=newConcept;document.querySelectorAll('[data-board]').forEach(button=>button.onclick=()=>{boardMode=button.dataset.board;document.querySelectorAll('[data-board]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));loadBoard();});document.querySelector('#city-filter').onsubmit=e=>{e.preventDefault();loadBoard();};await loadBoard();}
async function loadBoard(){const city=document.querySelector('#city-filter [name=city]').value,status=document.querySelector('#board-status');try{const data=await api('concepts?city='+encodeURIComponent(city));let rows=data.concepts;if(boardMode==='local'){const normal=v=>v.toLowerCase().trim().replace(/,\s*india$/,'').replace(/^bangalore$/,'bengaluru').replace(/^bombay$/,'mumbai').replace(/^new delhi$/,'delhi').replace(/^gurgaon$/,'gurugram');rows=rows.filter(c=>c.status==='open'&&normal(c.city)===normal(city));}else rows=rows.filter(c=>c.mine||c.involved);status.textContent=rows.length?`${rows.length} ${boardMode==='local'?'open concepts in '+city:'shoots and requests'}`:'No concepts here yet. Post the first one or try another city.';document.querySelector('#concept-list').innerHTML=rows.map(c=>`<article class="talent-concept"><p class="eyebrow">${esc(c.city)} / ${esc(c.date)}</p><h3>${esc(c.title)}</h3><p>${esc(c.brief.slice(0,200))}${c.brief.length>200?'…':''}</p><div>${tags(c.roles)}</div><p class="talent-muted">By ${esc(c.organiser)} ${c.mine?'· Your concept':''}</p>${stateTag(c.status)}<div class="talent-actions"><a class="button" href="/collaborations?concept=${esc(c.id)}">${c.mine?'Manage my shoot':'View concept'}</a></div></article>`).join('');}catch(error){status.textContent=error.message;}}
function newConcept(){main.innerHTML=`<a class="talent-back" href="/collaborations">Back to collaborations</a><p class="eyebrow">YOUR IDEA. YOUR CREATIVE TEAM.</p><h1>Start with<br><em>a concept.</em></h1><p>You’ll organise this shoot as a ${esc(account.label.toLowerCase())}. Tell people what you’re making and what they will receive.</p><form id="concept-form" class="talent-panel talent-form"><label>Concept title<input name="title" required maxlength="100" placeholder="e.g. A modern take on the Padmavati muse"></label><label>The concept & visual direction<textarea name="brief" required maxlength="1800" placeholder="The mood, the looks and the images you want to create"></textarea></label><div class="talent-fields"><label>City<input name="city" required value="${esc(account.city)}" maxlength="100"></label><label>Planned shoot date<input name="date" type="date" min="${new Date().toISOString().slice(0,10)}" required></label></div><label>Venue plan<input name="venue" maxlength="300" placeholder="e.g. Studio to be agreed by the selected team"></label><label>Who are you looking for?</label><div class="talent-role-checks">${['model','makeup','hair','designer','photographer'].filter(r=>r!==account.profession).map(r=>`<label class="check"><input type="checkbox" name="roles" value="${r}">${talentLabels[r]}</label>`).join('')}</div><label>Collaboration terms & shared costs<textarea name="exchange" required maxlength="800" placeholder="e.g. Unpaid portfolio collaboration. Each member receives 8 edited images with credits. No studio booked; discuss any travel or venue costs before committing."></textarea></label><label class="check"><input type="checkbox" name="consent" required>Everyone must agree image usage, credits, delivery and any costs before the shoot.</label><button type="submit" class="button">Publish concept</button><p role="status" class="talent-status"></p></form>`;wireForm('#concept-form',async(form,data)=>{const result=await api('concepts','POST',{...Object.fromEntries(data),roles:data.getAll('roles'),consent:data.has('consent')});location.href='/collaborations?concept='+result.id;});}
async function concept(id){const data=await api('concepts/'+id);activeConcept=data.concept;const c=activeConcept,mine=c.requests.find(r=>r.personId===account.id),selected=c.requests.filter(r=>r.status==='selected');main.innerHTML=`<a class="talent-back" href="/collaborations">Back to collaborations</a><p class="eyebrow">${esc(c.city)} / ${esc(c.date)}</p><h1>${esc(c.title)}</h1>${stateTag(c.status)}<div class="talent-panel"><div class="talent-identity">${avatar(c.organiser,true)}<p><b>${esc(c.organiser.name)}</b><br>Organiser · ${esc(c.organiser.label)}</p></div><p class="talent-pre">${esc(c.brief)}</p><p><b>Venue plan</b><br>${esc(c.venue||'To be agreed with the team')}</p><p class="talent-pre"><b>Collaboration terms</b><br>${esc(c.exchange)}</p><p><b>Looking for</b></p>${tags(c.roles)}</div>${c.member?`<section aria-label="Your shoot workspace"><p class="eyebrow">${c.status==='finalised'?'YOUR FINALISED TEAM':'YOUR SHOOT WORKSPACE'}</p><h2>One concept.<br><em>Your creative team.</em></h2><div class="talent-grid">${[{...c.organiser,role:c.organiser.role,status:'organiser'},...selected].map(r=>`<article class="talent-panel"><div class="talent-identity">${avatar(r,true)}<div><b>${esc(r.name)}</b><br>${esc(talentLabels[r.role])}<br>${stateTag(r.status)}</div></div>${safeLink(r.portfolio,'View portfolio')}</article>`).join('')}${c.roles.filter(r=>!selected.some(s=>s.role===r)).map(r=>`<article class="talent-panel"><h3>${esc(talentLabels[r])}</h3><p class="talent-muted">Open place · waiting for selection</p></article>`).join('')}</div><div class="talent-panel"><h3>Studio brief</h3><p class="talent-pre">${esc(c.studioNote||'The organiser can add call time, venue details, agreed credits and delivery plans here. Only the selected team can see this brief.')}</p>${c.mine?`<form id="studio-note"><label>Private team notes<textarea name="note" maxlength="2500">${esc(c.studioNote)}</textarea></label><button class="talent-outline" type="submit">Save studio brief</button><p role="status" class="talent-status"></p></form>`:''}</div>${c.status==='open'?`<div class="talent-panel"><h3>Know someone for this shoot?</h3><p>Refer a collaborator with a link. They’ll sign in with their own profession and send a request. The organiser makes the final selection.</p><form id="invite-form"><label>Invite a<select name="role">${c.roles.map(r=>`<option value="${r}">${talentLabels[r]}</option>`).join('')}</select></label><button class="talent-outline" type="submit">Create referral link</button><p role="status" class="talent-status"></p></form><div id="invite-result"></div></div>`:''}</section>`:''}${c.mine?`<section class="talent-panel"><h2>Requests to join</h2><p>Review each person’s profile. Select one collaborator for each open role.</p>${c.requests.length?`<ul class="talent-list">${c.requests.map(r=>`<li><div class="talent-identity">${avatar(r,true)}<div><b>${esc(r.name)}</b><br>${esc(talentLabels[r.role])} · ${esc(r.city)} ${stateTag(r.status)}</div></div><p class="talent-pre">${esc(r.message)}</p>${r.referredBy?`<p>Referred by ${esc(r.referredBy)}</p>`:''}${safeLink(r.portfolio,'View portfolio')}${c.status==='open'&&['requested','selected'].includes(r.status)?`<div class="talent-actions">${r.status==='requested'?`<button class="button" data-decision="${esc(r.id)}" data-approve="true" type="button">Approve for this shoot</button>`:''}<button class="talent-outline" data-decision="${esc(r.id)}" data-approve="false" type="button">Decline</button></div>`:''}</li>`).join('')}</ul>`:'<p>No requests yet. Refer people you’d like to collaborate with.</p>'}${c.status==='open'?`<div class="talent-actions"><button id="finalise" type="button" class="button">Finalise this team</button><button id="cancel-shoot" type="button" class="talent-outline">Cancel concept</button></div><p class="talent-muted">Finalising locks the selected team. Fill all requested roles first.</p>`:''}</section>`:mine&&['requested','selected'].includes(mine.status)?`<section class="talent-panel"><h3>Your request</h3>${stateTag(mine.status)}${c.status==='open'&&['requested','selected'].includes(mine.status)?'<p><button class="talent-outline" id="withdraw-request" type="button">Withdraw my request</button></p>':''}</section>`:c.status==='open'&&c.roles.includes(account.profession)?`<form class="talent-panel talent-form" id="request-form"><h2>Bring your ${esc(account.profession==='model'?'presence':account.label.toLowerCase())}.</h2><p>You’re requesting the ${esc(account.label.toLowerCase())} place as ${esc(account.name)}.</p><label>Introduce yourself<textarea name="message" required maxlength="800" placeholder="Why this concept speaks to you, your availability and what you can contribute"></textarea></label><label>Your portfolio link (optional)<input name="portfolio" type="url" placeholder="https://" maxlength="500"></label><label class="check"><input type="checkbox" name="consent" required>I have read the concept and collaboration terms. I’ll confirm the details with the team before the shoot.</label><button class="button" type="submit">Send request</button><p role="status" class="talent-status"></p></form>`:`<p class="talent-panel">${c.status==='open'?'This shoot isn’t looking for your registered profession. Try another concept or post your own.':'This shoot is no longer accepting requests.'}</p>`}`;
 wireForm('#request-form',async(form,data)=>{await api('concepts/'+id+'/request','POST',{...Object.fromEntries(data),consent:data.has('consent'),invite:params.get('invite')||''});await concept(id);notify('Request sent to the organiser.');});
 wireForm('#studio-note',async(form,data)=>{await api('concepts/'+id+'/note','POST',Object.fromEntries(data));form.querySelector('[role=status]').textContent='Team brief saved.';});
 wireForm('#invite-form',async(form,data)=>{const result=await api('concepts/'+id+'/invite','POST',Object.fromEntries(data));document.querySelector('#invite-result').innerHTML=`<label>Share this referral link<input id="invite-link" readonly value="${esc(result.url)}"></label><button class="talent-outline" id="copy-invite" type="button">Copy referral link</button>`;form.querySelector('[role=status]').textContent='Link ready. Share it with the collaborator you know.';document.querySelector('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(result.url);notify('Referral link copied.');}catch{document.querySelector('#invite-link').select();notify('Select and copy the referral link.');}};});
 document.querySelectorAll('[data-decision]').forEach(button=>button.onclick=()=>action(button,async()=>{await api('concepts/'+id+'/decision','POST',{requestId:button.dataset.decision,approve:button.dataset.approve==='true'});await concept(id);}));
 document.querySelector('#finalise')?.addEventListener('click',e=>action(e.target,async()=>{await api('concepts/'+id+'/finalise','POST',{});await concept(id);notify('Your team is finalised.');}));
 document.querySelector('#cancel-shoot')?.addEventListener('click',e=>{if(confirm('Cancel this concept? It will stop accepting requests.'))action(e.target,async()=>{await api('concepts/'+id+'/cancel','POST',{});await concept(id);});});
 document.querySelector('#withdraw-request')?.addEventListener('click',e=>action(e.target,async()=>{await api('concepts/'+id+'/withdraw','POST',{});await concept(id);}));
}
async function action(button,work){button.disabled=true;notify('Saving…');try{await work();if(message.textContent==='Saving…')notify('Saved.');}catch(error){notify(error.message);}finally{if(button.isConnected)button.disabled=false;}}
async function affiliations(){const data=await api('affiliations');if(account.profession==='agency'){main.innerHTML=`<a class="talent-back" href="/workspace">My studio</a><p class="eyebrow">AGENCY / MODEL APPLICATIONS</p><h1>The next face.<br><em>Your next connection.</em></h1>${!data.activated?'<p>Activate your approved agency account before reviewing applications.</p><a class="button" href="/agency-dashboard">Open agency dashboard</a>':data.requests.length?`<ul class="talent-list">${data.requests.map(r=>`<li><h3>${esc(r.name)}</h3><p>${esc(r.city)} ${stateTag(r.status)}</p><p>${esc(r.message)}</p>${safeLink(r.portfolio,'View portfolio')}${r.status==='pending'?`<div class="talent-actions"><button class="button" data-affiliation="${r.id}" data-approve="true">Approve affiliation</button><button class="talent-outline" data-affiliation="${r.id}" data-approve="false">Decline</button></div>`:''}</li>`).join('')}</ul>`:'<p class="talent-panel">No model applications yet. Requests addressed to your agency will appear here.</p>'}`;document.querySelectorAll('[data-affiliation]').forEach(button=>button.onclick=()=>action(button,async()=>{await api('affiliation-decision','POST',{id:button.dataset.affiliation,approve:button.dataset.approve==='true'});await affiliations();}));return;}
 const enrolled=data.affiliations.filter(a=>a.status==='approved');main.innerHTML=`<a class="talent-back" href="/workspace">My studio</a><p class="eyebrow">MODEL / YOUR AGENCY CONNECTIONS</p><h1>Your talent.<br><em>Your kind of agency.</em></h1><section class="talent-panel"><h2>My enrolled agencies</h2>${enrolled.length?enrolled.map(a=>`<p><b>${esc(a.name)}</b> · ${esc(a.city)} ${stateTag(a.status)}</p>`).join(''):'<p>You’re not enrolled with an agency through GLOSS yet.</p><a class="button" href="#agency-enrolment">Enrol with agency</a>'}</section>${data.affiliations.some(a=>a.status!=='approved')?`<section class="talent-panel"><h3>My applications</h3>${data.affiliations.filter(a=>a.status!=='approved').map(a=>`<p><b>${esc(a.name)}</b> · ${esc(a.city)} ${stateTag(a.status)}</p>`).join('')}</section>`:''}<section id="agency-enrolment"><h2>Make your introduction.</h2><p>Only agencies enrolled with GLOSS are listed. Sending an application doesn’t confirm representation; the agency must approve it.</p><div class="talent-fields"><label>City<select id="aff-city"><option value="">All cities</option>${[...new Set(data.agencies.map(a=>a.city))].sort().map(city=>`<option>${esc(city)}</option>`).join('')}</select></label><label>Modelling field<select id="aff-field"><option value="">All fields</option>${['E-commerce','Photoshoots','Print','Runway','Editorial','Beauty','Commercial'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><div id="agency-cards" class="talent-grid"></div><div id="agency-apply"></div></section>`;
 const render=()=>{const city=document.querySelector('#aff-city').value,field=document.querySelector('#aff-field').value,rows=data.agencies.filter(a=>(!city||a.city===city)&&(!field||a.modeling_fields.split(',').map(x=>x.trim()).includes(field)));document.querySelector('#agency-cards').innerHTML=rows.length?rows.map(a=>`<article class="talent-panel"><h3>${esc(a.name)}</h3><p>${esc(a.city)}</p><p>${esc(a.description)}</p>${tags(a.modeling_fields.split(','))}<div class="talent-actions">${data.affiliations.some(f=>f.agency_id===a.id)?'<span class="talent-tag">Application on file</span>':`<button class="button" type="button" data-apply="${a.id}">Apply to enrol</button>`}</div></article>`).join(''):'<p class="talent-panel">No enrolled agencies match these filters yet. Check back as the network grows.</p>';document.querySelectorAll('[data-apply]').forEach(button=>button.onclick=()=>{const a=data.agencies.find(a=>a.id===button.dataset.apply);document.querySelector('#agency-apply').innerHTML=`<form id="aff-form" class="talent-panel talent-form"><h3>Introduce yourself to ${esc(a.name)}</h3><label>Portfolio link<input name="portfolio" type="url" maxlength="500" placeholder="https:// — leave blank to use your published GLOSS portfolio"></label><label>Your introduction<textarea name="message" maxlength="800" required></textarea></label><label class="check"><input name="consent" type="checkbox" required>I agree to share my name, city, introduction and portfolio with this agency.</label><button class="button" type="submit">Send enrolment request</button><p class="talent-status" role="status"></p></form>`;document.querySelector('#agency-apply').scrollIntoView({behavior:'smooth'});wireForm('#aff-form',async(form,fd)=>{await api('affiliations','POST',{...Object.fromEntries(fd),agencyId:a.id,consent:fd.has('consent')});await affiliations();notify('Application sent. You’ll see the agency here once approved.');});});};document.querySelector('#aff-city').onchange=render;document.querySelector('#aff-field').onchange=render;render();}
(async()=>{try{account=(await api('account')).account;if(location.pathname==='/join'){join();return;}if(!account){location.href='/join?next='+encodeURIComponent(location.pathname+location.search);return;}if(location.pathname==='/collaborations'){if(params.get('concept'))await concept(params.get('concept'));else await board();}else if(location.pathname==='/affiliations')await affiliations();else workspace();}catch(error){main.innerHTML=`<h1>Your GLOSS studio.</h1><p class="talent-error">${esc(error.message)}</p><a class="button" href="/workspace">Back to my studio</a>`;}})();
